import { InkEditor } from "../../../../src/display/editor/ink.js";

describe("InkEditor", () => {
  describe("onScaleChanging", () => {
    let inkEditor;
    let mockParent;
    let mockDrawLayer;
    let mockDrawingOptions;
    let mockParameters;
    let mockViewport;
    let mockUiManager;
    let mockDrawOutlines;

    beforeEach(() => {
      mockDrawLayer = {
        updateProperties: jest.fn()
      };

      mockDrawingOptions = {
        updateSVGProperty: jest.fn(),
        toSVGProperties: jest.fn().mockReturnValue({ "stroke-width": 2 })
      };

      mockViewport = {
        rotation: 0,
        rawDims: {
          pageWidth: 612,
          pageHeight: 792,
          pageX: 0,
          pageY: 0
        }
      };

      mockUiManager = {
        viewParameters: {
          rotation: 0
        }
      };

      mockDrawOutlines = {
        updateParentDimensions: jest.fn().mockReturnValue({ x: 0, y: 0, width: 100, height: 100 })
      };

      mockParent = {
        drawLayer: mockDrawLayer,
        pageIndex: 1,
        viewport: mockViewport,
        scale: 1
      };

      mockParameters = {
        parent: mockParent,
        id: "test-id",
        uiManager: mockUiManager,
        name: "inkEditor"
      };

      inkEditor = new InkEditor(mockParameters);
      inkEditor._drawId = "test-draw-id";
      inkEditor._drawingOptions = mockDrawingOptions;
      inkEditor.parentDimensions = [100, 100];
      inkEditor._drawOutlines = mockDrawOutlines;
    });

    it("should do nothing when parent is not set", () => {
      inkEditor.parent = null;
      const superSpy = jest.spyOn(Object.getPrototypeOf(Object.getPrototypeOf(inkEditor)), "onScaleChanging");

      inkEditor.onScaleChanging();

      expect(superSpy).not.toHaveBeenCalled();
      expect(mockDrawingOptions.updateSVGProperty).not.toHaveBeenCalled();
      expect(mockDrawLayer.updateProperties).not.toHaveBeenCalled();
    });

    it("should call super.onScaleChanging when parent is set", () => {
      const superSpy = jest.spyOn(Object.getPrototypeOf(Object.getPrototypeOf(inkEditor)), "onScaleChanging");

      inkEditor.onScaleChanging();

      expect(superSpy).toHaveBeenCalledTimes(1);
    });

    it("should update SVG property and call parent drawLayer with correct parameters", () => {
      inkEditor.onScaleChanging();

      expect(mockDrawingOptions.updateSVGProperty).toHaveBeenCalledWith("stroke-width");
      expect(mockDrawingOptions.toSVGProperties).toHaveBeenCalledTimes(1);
      expect(mockDrawLayer.updateProperties).toHaveBeenCalledWith(
        "test-draw-id",
        { "stroke-width": 2 }
      );
    });

    it("should handle different draw IDs correctly", () => {
      inkEditor._drawId = "another-draw-id";

      inkEditor.onScaleChanging();

      expect(mockDrawLayer.updateProperties).toHaveBeenCalledWith(
        "another-draw-id",
        expect.any(Object)
      );
    });

    it("should handle different SVG properties from drawingOptions", () => {
      const mockProperties = { "stroke-width": 3, opacity: 0.5 };
      mockDrawingOptions.toSVGProperties.mockReturnValue(mockProperties);

      inkEditor.onScaleChanging();

      expect(mockDrawLayer.updateProperties).toHaveBeenCalledWith(
        "test-draw-id",
        mockProperties
      );
    });

    it("should work when parent drawLayer is not available", () => {
      mockParent.drawLayer = null;

      expect(() => {
        inkEditor.onScaleChanging();
      }).not.toThrow();
    });
  });
});

